SELECT "department" AS "40d4339a-1d62-4e97-b44e-88c320834387.department", "sub_department" AS "40d4339a-1d62-4e97-b44e-88c320834387.sub_department", "account_group" AS "40d4339a-1d62-4e97-b44e-88c320834387.account_group", "account_id" AS "40d4339a-1d62-4e97-b44e-88c320834387.account_id", "account_name" AS "40d4339a-1d62-4e97-b44e-88c320834387.account_name", "cost_center" AS "40d4339a-1d62-4e97-b44e-88c320834387.cost_center", "project_code" AS "40d4339a-1d62-4e97-b44e-88c320834387.project_code"
FROM "AwsDataCatalog"."cppib_shared"."department_account_cost_center_map"

/* cppi::9334b633b01fea3944f04a73f709b583afb3b321df58ecc6af5432d05cc48762 */
